code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    exterior = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not exterior[nr][nc]:
                exterior[nr][nc] = True
                q.append((nr, nc))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen:
                continue
            comp = []
            q = deque([(r,c)])
            seen.add((r,c))
            while q:
                y,x = q.popleft()
                comp.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx = y+dy,x+dx
                        if (dy or dx) and 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny,nx) not in seen:
                            seen.add((ny,nx))
                            q.append((ny,nx))
            neighbors = set()
            has_inside = False
            for y,x in comp:
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx = y+dy,x+dx
                        if (dy or dx) and 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0:
                            neighbors.add((ny,nx))
                            if not exterior[ny][nx]:
                                has_inside = True
            if has_inside:
                for y,x in neighbors:
                    out[y][x] = 3 if not exterior[y][x] else 2
    return out
'''
